#[test]
fn extracts_text_subtitles_as_srt() {
    let Some(env) = env() else { return };
    let cancel = CancelFlag::new();
    let srt = extract_text_subtitles(&env.sidecars, &fixture(env, "tone.mkv"), 2, &cancel).unwrap();
    assert!(srt.contains("00:00:01,000 --> 00:00:03,000"), "{srt}");
    assert!(srt.contains("Conjunction junction,"), "{srt}");
    assert!(srt.contains("Hooking up words and phrases"), "{srt}");

    let from_ass =
        extract_text_subtitles(&env.sidecars, &fixture(env, "tone.mkv"), 3, &cancel).unwrap();
    assert!(from_ass.contains("Lolly, lolly, lolly"), "{from_ass}");
    assert!(
        !from_ass.contains("{\\i1}"),
        "ASS override tags are converted: {from_ass}"
    );

    let from_mp4 =
        extract_text_subtitles(&env.sidecars, &fixture(env, "subs.mp4"), 1, &cancel).unwrap();
    assert!(from_mp4.contains("what's your function?"), "{from_mp4}");

    // Stream 1 of tone.mkv is audio: not a text subtitle.
    let err =
        extract_text_subtitles(&env.sidecars, &fixture(env, "tone.mkv"), 1, &cancel).unwrap_err();
    assert!(matches!(err, MediaError::ToolFailed { .. }), "{err:?}");
}

#[test]
fn scans_a_ripped_disc_folder() {
    let Some(env) = env() else { return };
    let folder = fixture(env, "SCHOOLHOUSE_ROCK_D1");
    let s = scan_folder(
        &env.sidecars,
        &folder,
        &ScanOptions::default(),
        &CancelFlag::new(),
    )
    .unwrap();

    let roles: Vec<(&str, FileRole)> = s.files.iter().map(|f| (f.id.0.as_str(), f.role)).collect();
    assert_eq!(
        roles,
        [
            ("title_t00.mkv", FileRole::PlayAll),
            ("title_t01.mkv", FileRole::Candidate),
            ("title_t02.mkv", FileRole::Candidate),
            ("title_t03.mkv", FileRole::Candidate),
            ("title_t04.mkv", FileRole::Ignored),
            ("title_t05.mkv", FileRole::Ignored),
        ]
    );
    assert_eq!(s.candidate_count, 3);
    assert_eq!(s.show_guess.as_deref(), Some("Schoolhouse Rock"));
    let play_all = s.play_all.as_ref().expect("play-all");
    assert_eq!(play_all.chapter_count, 4);
    assert_eq!(play_all.chapters_matched, 3);
    assert!(near(play_all.candidates_total_s, 83.0, 0.5));
    // Chapters all match; the duration is 14% over the files found (a title was not ripped).
    assert!(play_all.confidence > 0.7, "{}", play_all.confidence);

    assert!(s.files[5].probe.is_none());
    assert!(s.warnings.contains(&ScanWarning::MissingShortTitles {
        chapters: 4,
        short_files: 3
    }));
    assert!(s.warnings.contains(&ScanWarning::UnsupportedDiscFolder {
        folder: "VIDEO_TS".into(),
        format: DiscFolderFormat::Dvd
    }));
    assert!(
        s.warnings.iter().any(|w| matches!(
            w,
            ScanWarning::Unreadable { file_id, reason }
                if file_id.0 == "title_t05.mkv" && reason.starts_with("The file could not be read")
        )),
        "{:?}",
        s.warnings
    );
    assert_eq!(s.warnings.len(), 3, "{:?}", s.warnings);
}

#[test]
fn scanning_reports_files_without_audio() {
    let Some(env) = env() else { return };
    let dir = tempfile::tempdir().unwrap();
    std::fs::copy(fixture(env, "silent-video.mkv"), dir.path().join("a.mkv")).unwrap();
    let s = scan_folder(
        &env.sidecars,
        dir.path(),
        &ScanOptions::default(),
        &CancelFlag::new(),
    )
    .unwrap();
    assert_eq!(s.files[0].role, FileRole::Ignored);
    assert_eq!(
        s.warnings,
        [ScanWarning::NoAudio {
            file_id: mi_types::FileId("a.mkv".into())
        }]
    );
}

#[test]
fn reads_every_supported_container_and_audio_codec() {
    let Some(env) = env() else { return };
    for (name, _, _, codec) in CODEC_MATRIX {
        let path = fixture(env, &format!("codecs/{name}"));
        let p = probe(&env.sidecars, &path, &CancelFlag::new())
            .unwrap_or_else(|e| panic!("{name}: probe failed: {e}"));
        assert_eq!(p.audio_streams[0].codec, *codec, "{name}");
        assert!(near(p.duration_s, 3.0, 0.2), "{name}: {} s", p.duration_s);
        let pcm = extract_audio(
            &env.sidecars,
            &path,
            &ExtractOptions::default(),
            &CancelFlag::new(),
        )
        .unwrap_or_else(|e| panic!("{name}: decode failed: {e}"));
        assert!(
            near(pcm.duration_s(), 3.0, 0.15),
            "{name}: {} s decoded",
            pcm.duration_s()
        );
        let f = frequency(&pcm.samples[1600..pcm.samples.len() - 1600]);
        assert!(near(f, 440.0, 10.0), "{name}: {f} Hz");
    }
}
